def drop_negative(weights: list[float]) -> list[float]:
    """Return the weights without negative values."""
    for w in weights:
        if w < 0:
            weights.remove(w)
    return weights

exercises.fix_solution:
def drop_negative(weights: list[float]) -> list[float]:
    """Return the weights without negative values."""
    return [w for w in weights if w >= 0]
